                if let Err(error) = &result {
                    reporting_owner.record_retry_failure(error);
                    crate::diagnostics::write_line(format_args!(
                        "switchd-rs: QMI retry stopped: {error}"
                    ));
                }
                result
            })

/// libusb QMI owner.
pub fn parse(path: &str) -> Result<Self, SelectorError> {
    let normalized = path.trim();
    if normalized.is_empty() || normalized.eq_ignore_ascii_case("auto") {
        return Ok(Self::PriorityList(DEFAULT_DEVICE_IDS.to_vec()));
    }
    let (vendor, product) = normalized.split_once(':').ok_or_else(|| {
        SelectorError(format!(
            "invalid QMI libusb path {path:?} (want VID:PID, e.g. 2ca3:4006)"
        ))
    })?;
    if product.contains(':') {
        return Err(SelectorError(format!(
            "invalid QMI libusb path {path:?} (want VID:PID, e.g. 2ca3:4006)"
        )));
    }
    let vendor_id = parse_hex_u16(vendor)
        .map_err(|error| SelectorError(format!("invalid VID in path {path:?}: {error}")))?;
    let product_id = parse_hex_u16(product)
        .map_err(|error| SelectorError(format!("invalid PID in path {path:?}: {error}")))?;
    Ok(Self::Exact(UsbDeviceId {
        vendor_id,
        product_id,
    }))
}

pub fn device_ids(&self) -> &[UsbDeviceId] {
    match self {
        Self::PriorityList(ids) => ids,
        Self::Exact(id) => std::slice::from_ref(id),
    }
}

pub(crate) fn validate_response(
    response: &OwnedPacket,
    service: u16,
    message: u16,
) -> Result<(), QmiServiceClientError> {
    if response.meta.service != service {
        return Err(CodecError::UnexpectedService {
            expected: service,
            actual: response.meta.service,
        }
        .into());
    }
    if response.meta.message_id != message {
        return Err(CodecError::UnexpectedMessage {
            expected: message,
            actual: response.meta.message_id,
        }
        .into());
    }
    if response.meta.message_control_flags & 0x02 == 0 || response.is_indication() {
        return Err(CodecError::MalformedField("QMI response control flag").into());
    }
    response.check_result()?;
    Ok(())

